  onToggleExpand: () => void;
  onReply: () => void;
  onReplyAll: () => void;
  onForward: () => void;
  onToggleStar: () => void;
}) {

import {
  Reply,
  ReplyAll,
  Forward,
  Star,
  Paperclip,
  ChevronUp,
  Mail,
} from 'lucide-react';

